const ELEMENTS = "H He Li Be B C N O F Ne Na Mg Al Si P S Cl Ar K Ca Sc Ti V Cr Mn Fe Co Ni Cu Zn Ga Ge As Se Br Kr Rb Sr Y Zr Nb Mo Tc Ru Rh Pd Ag Cd In Sn Sb Te I Xe Cs Ba La Ce Pr Nd Pm Sm Eu Gd Tb Dy Ho Er Tm Yb Lu Hf Ta W Re Os Ir Pt Au Hg Tl Pb Bi Po At Rn Fr Ra Ac Th Pa U Np Pu Am Cm Bk Cf Es Fm Md No Lr Rf Db Sg Bh Hs Mt Ds Rg Cn Nh Fl Mc Lv Ts Og".split(" ");
function elementSymbol(value) {
	const trimmed = value.trim();
	if (/^\d+$/.test(trimmed)) {
		const z = Number(trimmed);
		if (z < 1 || z > ELEMENTS.length) throw new Error(`不支持原子序数 ${trimmed}。`);
		return ELEMENTS[z - 1];
	}
	const result = trimmed[0]?.toUpperCase() + trimmed.slice(1).toLowerCase();
	if (!ELEMENTS.includes(result)) throw new Error(`无法识别元素“${value}”；不会丢弃该原子。`);
	return result;
}
function atomicNumber(element) {
	const n = ELEMENTS.indexOf(element) + 1;
	if (!n) throw new Error(`未知元素 ${element}。`);
	return n;
}

